INSERT INTO categorias (id, nombre, slug) VALUES (2, 'Almuerzos', 'almuerzos') ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (1, 1, 'Pan con palta', 'Pan francés crocante con palta fresca aplastada y un toque de sal.', '["4 panes franceses","2 paltas maduras grandes","Sal al gusto","1 limón"]'::jsonb, '["Cortar el pan francés por la mitad sin llegar a separarlo del todo y tostarlo unos minutos hasta que la corteza quede crocante","Pelar la palta madura y retirar la pepa, colocando la pulpa en un bowl","Aplastar la palta con un tenedor hasta lograr una pasta suave con algunos trozos","Sazonar con sal al gusto y unas gotas de limón, mezclando bien para evitar que se oxide","Untar generosamente la palta sazonada sobre el pan tostado","Servir de inmediato para disfrutar el pan crocante con la palta fresca"]'::jsonb, 10, 'facil', '/assets/images/recetas/pan_con_palta.jpg', 'Café pasado', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (2, 1, 'Pan con chicharrón', 'Chicharrón de cerdo crocante servido en pan francés con salsa criolla y camote.', '["4 panes franceses","500 g de panceta o pierna de cerdo","2 camotes medianos, en rodajas","1 cebolla roja mediana","2 limones","1 ají amarillo, en tiras"]'::jsonb, '["Cortar la carne de cerdo en trozos medianos y sazonar con sal, comino y ajo molido","Freír el cerdo en su propia grasa a fuego medio hasta que quede dorado y crocante por fuera y jugoso por dentro","Pelar y cortar el camote en rodajas gruesas y freírlo aparte hasta que dore","Cortar la cebolla en pluma fina y lavarla con agua fría para suavizar su sabor","Preparar la salsa criolla mezclando la cebolla con limón, sal, ají amarillo en tiras finas y un poco de culantro picado","Abrir el pan francés y colocar dentro el chicharrón caliente junto con las rodajas de camote frito","Coronar con abundante salsa criolla y servir de inmediato"]'::jsonb, 35, 'media', '/assets/images/recetas/pan_con_chicharron.jpg', 'Café pasado', 'Camote frito', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (3, 1, 'Pan con tamal', 'Tamal de maíz relleno de pollo envuelto en pan, clásico desayuno limeño.', '["4 tamales de maíz con pollo","150 g de pollo deshilachado adicional","4 panes franceses","1 taza de salsa criolla"]'::jsonb, '["Colocar el tamal envuelto en su panca sobre una vaporera y calentar por 10 minutos hasta que esté bien caliente","Retirar con cuidado la panca de choclo o plátano que envuelve el tamal","Cortar el tamal en rodajas gruesas, procurando que conserve el relleno de pollo en cada trozo","Preparar una salsa criolla fresca con cebolla en pluma, limón, sal y un toque de ají amarillo","Abrir el pan francés por la mitad y colocar las rodajas de tamal dentro","Añadir la salsa criolla por encima y cerrar el pan","Servir tibio acompañado de una taza de café pasado"]'::jsonb, 15, 'facil', '/assets/images/recetas/pan_con_tamal.jpg', 'Café pasado', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (4, 1, 'Pan con tortilla', 'Tortilla de verduras esponjosa servida caliente en pan francés.', '["4 huevos","1 taza de verduras picadas (cebolla, tomate y pimiento)","4 panes franceses","1/2 cucharadita de sal","1/4 cucharadita de pimienta"]'::jsonb, '["Picar finamente las verduras (cebolla, tomate, pimiento) en cubos pequeños","Batir los huevos enérgicamente en un bowl junto con sal y pimienta al gusto","Incorporar las verduras picadas a los huevos batidos y mezclar bien","Calentar una sartén con un poco de aceite a fuego medio","Verter la mezcla y cocinar tapado unos 3 minutos hasta que cuaje por debajo","Voltear la tortilla con ayuda de un plato y cocinar el otro lado hasta dorar ligeramente","Colocar la tortilla caliente dentro del pan francés recién partido y servir"]'::jsonb, 15, 'facil', '/assets/images/recetas/pan_con_tortilla.jpg', 'Emoliente', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (5, 1, 'Pan con huevo', 'Huevo frito o revuelto servido en pan francés recién horneado.', '["4 huevos","4 panes franceses","Sal al gusto","2 cucharadas de aceite"]'::jsonb, '["Calentar un chorrito de aceite en una sartén pequeña a fuego medio","Romper el huevo directamente sobre la sartén caliente, cuidando que la yema no se rompa si se desea frito","Sazonar con sal apenas se vierte el huevo","Cocinar hasta que la clara esté firme y la yema al punto deseado, o revolver constantemente si se prefiere revuelto","Retirar el huevo con una espátula procurando mantener su forma","Colocar el huevo caliente dentro del pan francés recién abierto y servir de inmediato"]'::jsonb, 8, 'facil', '/assets/images/recetas/pan_con_huevo.jpg', 'Leche con café', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (6, 1, 'Quinua', 'Bebida caliente y nutritiva a base de quinua, canela y manzana.', '["1 taza de quinua (200 g)","2 litros de agua","1 rama de canela","2 clavos de olor","1 manzana, picada","1/2 taza de azúcar"]'::jsonb, '["Lavar bien la quinua en agua fría, frotándola con las manos hasta que el agua salga clara, para retirar la saponina","Colocar la quinua en una olla con abundante agua junto con la canela en rama y el clavo de olor","Cocer a fuego medio durante 20 minutos, revolviendo de vez en cuando, hasta que el grano reviente","Pelar y picar la manzana en cubos pequeños e incorporarla a la olla","Añadir azúcar al gusto y dejar hervir 5 minutos más para que se integren los sabores","Retirar la canela y el clavo, y licuar ligeramente si se prefiere una textura más suave","Servir bien caliente"]'::jsonb, 25, 'facil', '/assets/images/recetas/quinua.jpg', NULL, 'Pan con queso fresco', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (7, 1, 'Avena', 'Refresco espeso y dulce de avena con canela, típico del desayuno peruano.', '["1 taza de avena","1 litro de agua","1 rama de canela","1 litro de leche","1/2 taza de azúcar"]'::jsonb, '["Colocar la avena en una olla con agua y la canela en rama","Cocer a fuego medio durante 15 minutos, revolviendo con frecuencia para que no se pegue en el fondo","Retirar la canela una vez que la avena esté suave y el líquido haya espesado ligeramente","Licuar la avena cocida junto con la leche hasta obtener una mezcla homogénea","Colar si se desea una textura más fina, o dejar tal cual para mayor cuerpo","Endulzar con azúcar al gusto y servir bien frío o caliente según preferencia"]'::jsonb, 20, 'facil', '/assets/images/recetas/avena.jpg', NULL, 'Pan con palta', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (8, 1, 'Maca', 'Bebida energizante a base de maca en polvo, típica de la sierra peruana.', '["2 cucharadas de maca en polvo","1 litro de leche o agua","1 pizca de canela molida","Azúcar al gusto"]'::jsonb, '["Entibiar la leche o el agua en una olla pequeña sin dejar que hierva","Disolver la maca en polvo poco a poco en el líquido tibio, batiendo para evitar grumos","Añadir una pizca de canela molida para realzar el sabor","Endulzar con azúcar al gusto","Batir enérgicamente con una cuchara o con un molinillo hasta que quede espumosa","Servir caliente de inmediato"]'::jsonb, 10, 'facil', '/assets/images/recetas/maca.jpg', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (9, 1, 'Emoliente', 'Infusión caliente de hierbas y cebada, bebida callejera tradicional.', '["1/2 taza de cebada","2 cucharadas de linaza","1 puñado de cola de caballo","2 litros de agua","2 limones","Miel al gusto"]'::jsonb, '["Lavar la cebada, la linaza y la cola de caballo en agua fría","Colocar todos los ingredientes en una olla grande con abundante agua","Hervir a fuego medio durante 25 minutos hasta que el agua tome un color amarillento y las semillas de linaza suelten su mucílago","Colar el líquido presionando bien las hierbas para extraer todo su sabor","Servir en un vaso o taza y añadir el jugo de limón y miel al gusto justo antes de tomar","Disfrutar caliente, revolviendo bien para integrar la miel"]'::jsonb, 30, 'media', '/assets/images/recetas/emoliente.jpg', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (10, 1, 'Humitas', 'Masa de choclo tierno al vapor envuelta en su propia panca, dulce o salada.', '["8 choclos tiernos con panca","4 cucharadas de manteca","1 cucharadita de anís","Sal o azúcar al gusto","16 pancas de choclo para envolver"]'::jsonb, '["Desgranar los choclos tiernos y reservar las pancas más grandes y en buen estado para envolver","Moler los granos de choclo en una licuadora o batán junto con el anís hasta obtener una masa espesa","Calentar la manteca en una sartén y mezclarla con la masa de choclo, sazonando con sal o azúcar según se prefiera dulce o salada","Cocinar la masa a fuego suave por 5 minutos, revolviendo constantemente hasta que espese un poco más","Colocar dos cucharadas de masa en el centro de cada panca y doblar los extremos formando un paquete","Amarrar cada humita con tiras de la misma panca o pabilo","Colocar las humitas en una olla con agua hirviendo, apoyadas sobre más pancas en el fondo, y cocer al vapor durante 40 minutos","Retirar, dejar reposar unos minutos y servir calientes"]'::jsonb, 60, 'dificil', '/assets/images/recetas/humitas.jpg', 'Café pasado', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (11, 1, 'Tamales', 'Masa de maíz rellena de pollo o cerdo, envuelta en hoja de plátano y cocida al vapor.', '["1 kg de maíz pelado","500 g de pollo o cerdo, en trozos","4 cucharadas de ají panca licuado","8 hojas de plátano","8 aceitunas de botija"]'::jsonb, '["Remojar el maíz pelado la noche anterior y luego molerlo hasta obtener una masa fina","Sofreír ají panca licuado con ajo y cebolla, e incorporarlo a la masa de maíz junto con manteca y sal, cocinando a fuego lento hasta espesar","Sazonar y cocer el pollo o cerdo en trozos con sal, comino y un poco del mismo aderezo de ají panca","Pasar las hojas de plátano por fuego directo unos segundos para flexibilizarlas y lavarlas bien","Colocar una porción de masa sobre la hoja, añadir un trozo de carne y una aceituna en el centro","Envolver la hoja formando un paquete rectangular y amarrar firmemente con pabilo o tiras de la misma hoja","Acomodar los tamales en una olla grande sobre una base de hojas y cocer al vapor durante 90 minutos","Verificar el punto de cocción, dejar reposar 10 minutos y servir calientes con salsa criolla"]'::jsonb, 90, 'dificil', '/assets/images/recetas/tamales.jpg', 'Café pasado', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (12, 1, 'Pan con queso fresco', 'Pan francés con láminas de queso fresco andino.', '["4 panes franceses","200 g de queso fresco","2 cucharadas de mantequilla"]'::jsonb, '["Cortar el pan francés por la mitad sin separarlo completamente","Untar una capa fina de mantequilla en ambos lados del pan","Cortar el queso fresco en láminas de aproximadamente medio centímetro de grosor","Rellenar el pan con dos o tres láminas de queso fresco","Presionar ligeramente para que el queso se adhiera bien y servir de inmediato"]'::jsonb, 5, 'facil', '/assets/images/recetas/pan_con_queso_fresco.jpg', 'Emoliente', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (13, 1, 'Pan con aceitunas', 'Pan francés con aceitunas de botija molidas al estilo criollo.', '["4 panes franceses","150 g de aceitunas de botija","1/2 ají amarillo, picado","100 g de queso fresco (opcional)"]'::jsonb, '["Deshuesar las aceitunas de botija con cuidado, retirando toda la pepa","Triturar las aceitunas en un mortero o procesadora hasta formar una pasta gruesa","Mezclar la pasta con un toque de ají amarillo picado y, si se desea, unos trozos pequeños de queso fresco","Probar y ajustar el sabor, ya que la aceituna aporta bastante sal por sí sola","Abrir el pan francés y untar generosamente la pasta de aceitunas","Servir de inmediato acompañado de café pasado"]'::jsonb, 10, 'facil', '/assets/images/recetas/pan_con_aceitunas.jpg', 'Café pasado', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (14, 1, 'Sándwich de pollo', 'Pollo deshilachado con mayonesa y apio, un clásico de panadería peruana.', '["2 pechugas de pollo (400 g)","4 cucharadas de mayonesa","1 tallo de apio, picado","4 panes franceses"]'::jsonb, '["Cocer la pechuga de pollo en agua con sal durante 20 minutos hasta que esté bien cocida","Dejar enfriar y deshilachar la pechuga con las manos o dos tenedores en tiras finas","Picar el apio en cubos muy pequeños","Mezclar el pollo deshilachado con la mayonesa y el apio picado hasta integrar bien","Sazonar con sal y pimienta al gusto","Rellenar el pan francés con la mezcla y servir frío o a temperatura ambiente"]'::jsonb, 25, 'facil', '/assets/images/recetas/sandwich_de_pollo.jpg', 'Chicha morada', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (15, 1, 'Sándwich de jamón', 'Pan francés con jamón y queso, simple y rápido.', '["4 panes franceses","8 láminas de jamón","8 láminas de queso","2 cucharadas de mantequilla"]'::jsonb, '["Cortar el pan francés por la mitad sin separarlo del todo","Untar una capa fina de mantequilla en ambos lados","Colocar una o dos láminas de jamón sobre el pan","Añadir una lámina de queso encima del jamón","Cerrar el pan y, si se desea, tostarlo ligeramente en sartén o plancha para que el queso se derrita un poco","Servir de inmediato"]'::jsonb, 5, 'facil', '/assets/images/recetas/sandwich_de_jamon.jpg', 'Jugo de papaya', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (16, 1, 'Jugo de papaya', 'Jugo espeso y dulce de papaya fresca con leche.', '["300 g de papaya (1/2 papaya mediana)","2 tazas de leche","3 cucharadas de azúcar","1 taza de hielo"]'::jsonb, '["Pelar la papaya, retirar las pepas y cortar la pulpa en trozos medianos","Colocar los trozos de papaya en la licuadora junto con la leche","Añadir azúcar al gusto y unos cubos de hielo","Licuar hasta obtener una mezcla suave y homogénea, sin grumos","Probar y ajustar el dulzor si es necesario","Servir bien frío de inmediato"]'::jsonb, 10, 'facil', '/assets/images/recetas/jugo_de_papaya.jpg', NULL, 'Pan con palta', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (17, 1, 'Jugo surtido', 'Combinado de frutas de estación licuadas, refrescante y nutritivo.', '["150 g de papaya","1 plátano","2 naranjas (jugo)","1 taza de leche"]'::jsonb, '["Pelar y trocear la papaya y el plátano","Exprimir la naranja para obtener su jugo, colando las semillas","Colocar las frutas troceadas en la licuadora junto con el jugo de naranja y la leche","Licuar a velocidad alta hasta integrar completamente todos los ingredientes","Colar si se desea una textura más ligera, o dejar espeso","Endulzar al gusto y servir frío de inmediato"]'::jsonb, 10, 'facil', '/assets/images/recetas/jugo_surtido.jpg', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (18, 1, 'Leche con café', 'Café pasado con leche caliente, el desayuno más clásico del Perú.', '["4 cucharadas de café molido","2 tazas de agua caliente","1 litro de leche","Azúcar al gusto"]'::jsonb, '["Colocar el café molido en un filtro de tela o de papel","Verter agua caliente lentamente sobre el filtro, dejando que el café pasado gotee en una jarra hasta obtener un concentrado oscuro","Calentar la leche en una olla aparte, cuidando que no llegue a hervir","Verter una porción del concentrado de café en cada taza","Completar con la leche caliente en la proporción deseada","Endulzar con azúcar al gusto y remover antes de servir"]'::jsonb, 10, 'facil', '/assets/images/recetas/leche_con_cafe.jpg', NULL, 'Pan con mantequilla', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (19, 1, 'Chocolate caliente', 'Chocolate de taza espeso y aromático con canela.', '["200 g de chocolate de taza","1 litro de leche","1 rama de canela","2 clavos de olor"]'::jsonb, '["Calentar la leche en una olla junto con la canela en rama y el clavo de olor","Cuando la leche esté caliente pero sin hervir, incorporar el chocolate de taza troceado","Revolver constantemente con una cuchara de madera hasta que el chocolate se disuelva por completo","Batir enérgicamente con un molinillo durante un par de minutos para generar espuma y homogeneizar","Retirar la canela y el clavo de olor","Servir bien caliente en tazas"]'::jsonb, 15, 'facil', '/assets/images/recetas/chocolate_caliente.jpg', NULL, 'Pan', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (20, 1, 'Infusión de hierbas', 'Infusión suave de hierbas aromáticas como manzanilla, anís y hierbaluisa.', '["1 cucharadita de manzanilla","1 cucharadita de anís","1 cucharadita de hierbaluisa","1 litro de agua","Miel al gusto"]'::jsonb, '["Poner a hervir agua en una olla pequeña","Retirar del fuego apenas rompa el hervor y añadir la manzanilla, el anís y la hierbaluisa","Tapar la olla y dejar reposar entre 5 y 8 minutos para que las hierbas suelten su aroma","Colar la infusión y servir en una taza","Endulzar con miel al gusto y remover antes de beber"]'::jsonb, 10, 'facil', '/assets/images/recetas/infusion_de_hierbas.jpg', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (21, 2, 'Lomo Saltado', 'Salteado criollo-chino de carne de res, cebolla, tomate y papas fritas.', '["600 g de lomo de res, en tiras","1 cebolla roja grande, en pluma","2 tomates, en gajos","3 papas grandes, fritas","4 cucharadas de sillao (salsa de soya)","1 ají amarillo, en tiras"]'::jsonb, '["Cortar el lomo de res en tiras gruesas, la cebolla en pluma y el tomate en gajos","Freír las papas en abundante aceite caliente hasta que doren y queden crocantes por fuera, luego reservar sobre papel absorbente","Calentar un wok o sartén amplia a fuego muy alto hasta que humee ligeramente","Saltear la carne por tandas pequeñas durante 1 a 2 minutos para sellarla sin que suelte demasiado jugo, y reservar","En el mismo wok, saltear la cebolla y el ají amarillo en tiras a fuego alto durante 1 minuto","Incorporar el tomate y saltear brevemente para que mantenga su textura firme","Regresar la carne al wok, añadir el sillao, sal y pimienta, y saltear todo junto 1 minuto más","Agregar las papas fritas al final, mezclando con movimientos rápidos para que se impregnen del jugo sin perder su crocancia","Servir de inmediato acompañado de arroz blanco"]'::jsonb, 30, 'media', '/assets/images/recetas/lomo_saltado.jpg', 'Chicha morada', 'Arroz blanco', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (22, 2, 'Ají de Gallina', 'Crema espesa de ají amarillo con gallina deshilachada sobre arroz.', '["600 g de pechuga de gallina","4 ajíes amarillos, licuados","2 rebanadas de pan de molde, remojadas en leche","1/2 taza de nueces, picadas","1/2 taza de queso parmesano, rallado"]'::jsonb, '["Cocer la pechuga de gallina en agua con sal, cebolla y apio durante 30 minutos, reservando el caldo","Deshilachar la gallina cocida en tiras finas con las manos","Remojar el pan de molde en leche tibia hasta que se ablande por completo","Licuar el ají amarillo sin pepas junto con el pan remojado, las nueces y un poco del caldo de gallina hasta obtener una crema lisa","Sofreír cebolla picada y ajo molido en aceite hasta que estén transparentes","Verter la crema licuada sobre el sofrito y cocinar a fuego medio, revolviendo constantemente para que no se pegue","Incorporar la gallina deshilachada y el queso parmesano rallado, y cocinar 10 minutos más hasta que espese","Ajustar la sal y añadir más caldo si queda demasiado espesa","Servir sobre arroz blanco, decorado con una rodaja de huevo duro y una aceituna"]'::jsonb, 50, 'media', '/assets/images/recetas/aji_de_gallina.jpg', 'Chicha morada', 'Arroz blanco', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (23, 2, 'Arroz con Pollo', 'Arroz verde aromático cocido con presas de pollo y verduras.', '["8 presas de pollo","3 tazas de arroz","2 atados de culantro, licuados","1 taza de arvejas","1 zanahoria, en cubos"]'::jsonb, '["Sazonar las presas de pollo con sal, comino y pimienta","Dorar el pollo en una olla grande con aceite caliente por todos sus lados y reservar","Licuar el culantro con un poco de agua o caldo hasta obtener un puré verde intenso","En la misma olla, sofreír cebolla, ajo y ají amarillo picados hasta que estén transparentes","Añadir el culantro licuado y cocinar a fuego medio durante 5 minutos para que pierda el sabor crudo","Incorporar el pollo dorado junto con la zanahoria en cubos y cubrir con caldo de pollo","Añadir el arroz lavado y cocinar tapado a fuego bajo, sin destapar, hasta que el arroz absorba todo el líquido","Cinco minutos antes de terminar la cocción, incorporar las arvejas","Dejar reposar tapado 5 minutos más antes de servir, esponjando el arroz con un tenedor"]'::jsonb, 45, 'media', '/assets/images/recetas/arroz_con_pollo.jpg', 'Chicha de jora', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (24, 2, 'Seco de Res', 'Guiso de carne de res en salsa de culantro, típico de la costa norte.', '["800 g de carne de res, en trozos","2 atados de culantro, licuados","1 taza de chicha de jora","1 taza de arvejas","300 g de zapallo loche, en cubos"]'::jsonb, '["Cortar la carne de res en trozos grandes y sazonar con sal, comino y pimienta","Sellar la carne en una olla con aceite bien caliente hasta dorar todos los lados, y reservar","Licuar el culantro con un poco de agua hasta obtener un puré bien verde","En la misma olla, sofreír cebolla, ajo y ají amarillo picados finamente","Incorporar el culantro licuado y cocinar 5 minutos a fuego medio removiendo constantemente","Regresar la carne a la olla, añadir la chicha de jora y suficiente caldo o agua hasta cubrir","Cocinar tapado a fuego lento durante 50 minutos, revisando de vez en cuando y añadiendo líquido si se reduce demasiado","Agregar el zapallo loche en cubos y las arvejas cuando la carne esté casi suave, cocinando 15 minutos más","Verificar que la carne se deshaga fácilmente con el tenedor antes de retirar del fuego","Servir caliente acompañado de frejoles y arroz blanco"]'::jsonb, 70, 'dificil', '/assets/images/recetas/seco_de_res.jpg', 'Chicha morada', 'Frejoles y arroz', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (25, 2, 'Carapulcra', 'Guiso afroperuano de papa seca con cerdo y maní tostado.', '["500 g de papa seca","500 g de carne de cerdo, en trozos","1 taza de maní tostado, molido","4 cucharadas de ají panca, licuado","30 g de chocolate (una onza)"]'::jsonb, '["Remojar la papa seca en agua tibia durante al menos 1 hora hasta que se hidrate y ablande","Sazonar el cerdo en trozos con sal, comino y pimienta","Dorar el cerdo en una olla con aceite caliente hasta sellar bien todos los lados, y reservar","Sofreír cebolla y ajo picados en la misma grasa hasta que estén transparentes","Añadir el ají panca licuado y cocinar 5 minutos removiendo para que no se pegue","Incorporar la papa seca escurrida y tostar ligeramente junto al aderezo por un par de minutos","Regresar el cerdo a la olla, cubrir con caldo caliente y cocinar tapado a fuego lento durante 40 minutos","Moler el maní tostado hasta obtener un polvo grueso e incorporarlo a la olla junto con una onza de chocolate rallado","Cocinar 20 minutos más a fuego muy bajo, revolviendo con frecuencia para que espese sin pegarse","Rectificar la sazón y servir caliente acompañado de arroz blanco"]'::jsonb, 90, 'dificil', '/assets/images/recetas/carapulcra.jpg', 'Chicha morada', 'Arroz blanco', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (26, 2, 'Tallarines Verdes', 'Pasta bañada en salsa de albahaca cremosa, acompañada de bistec.', '["500 g de tallarines","2 atados de albahaca","1 atado de espinaca","200 g de queso fresco","1/2 taza de nueces"]'::jsonb, '["Deshojar la albahaca y la espinaca, y blanquearlas en agua hirviendo por 30 segundos, luego pasarlas a agua con hielo para fijar el color","Licuar la albahaca y espinaca blanqueadas junto con el queso fresco, las nueces, un diente de ajo y un chorro de leche o caldo hasta obtener una salsa cremosa","Sofreír cebolla picada en un poco de aceite hasta que esté transparente","Verter la salsa licuada sobre el sofrito y cocinar a fuego bajo por 5 minutos, sin dejar que hierva fuerte para que no pierda el color","Cocer los tallarines en abundante agua con sal hasta que estén al dente, siguiendo el tiempo indicado en el paquete","Escurrir la pasta reservando un poco del agua de cocción","Mezclar los tallarines con la salsa verde caliente, añadiendo un poco del agua reservada si queda muy espesa","Freír o dorar el bistec aparte con sal y pimienta hasta el punto deseado","Servir los tallarines verdes coronados con el bistec en tiras"]'::jsonb, 30, 'facil', '/assets/images/recetas/tallarines_verdes.jpg', 'Limonada', 'Bistec apanado', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (27, 2, 'Causa Limeña', 'Puré de papa amarilla sazonado con ají y limón, relleno de pollo o atún.', '["1 kg de papa amarilla","3 ajíes amarillos, licuados","4 limones","2 paltas","300 g de pollo deshilachado o atún"]'::jsonb, '["Cocer la papa amarilla con cáscara en agua con sal hasta que esté bien suave, luego pelar y prensar en caliente","Sazonar el puré de papa con ají amarillo licuado, jugo de limón, sal y un chorrito de aceite, amasando hasta lograr una masa lisa sin grumos","Dejar enfriar la masa de papa a temperatura ambiente","Preparar el relleno mezclando pollo deshilachado o atún con mayonesa, cebolla picada y un toque de limón","Cortar la palta en láminas delgadas","Forrar un molde con film y colocar una capa de masa de papa presionando bien","Añadir una capa del relleno de pollo o atún y cubrir con láminas de palta","Terminar con otra capa de masa de papa, presionando para compactar","Desmoldar con cuidado, decorar la superficie y refrigerar al menos 30 minutos antes de servir"]'::jsonb, 40, 'media', '/assets/images/recetas/causa_limena.jpg', 'Chicha morada', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (28, 2, 'Papa a la Huancaína', 'Papas cocidas bañadas en salsa cremosa de ají amarillo y queso.', '["1 kg de papa blanca","4 ajíes amarillos","300 g de queso fresco","1 taza de leche","6 galletas de soda"]'::jsonb, '["Cocer las papas blancas con cáscara en agua con sal hasta que estén suaves al pincharlas con un tenedor","Dejar enfriar las papas, pelarlas y cortarlas en rodajas gruesas","Sofreír el ají amarillo sin pepas ni venas en un poco de aceite hasta que pierda el sabor picante fuerte","Licuar el ají sofrito junto con el queso fresco, la leche y las galletas de soda hasta obtener una crema espesa y homogénea","Probar y ajustar la sal, añadiendo más leche si la salsa queda demasiado espesa","Acomodar las rodajas de papa sobre un plato con hojas de lechuga","Bañar generosamente las papas con la salsa huancaína","Decorar con huevo duro en rodajas y una aceituna de botija antes de servir"]'::jsonb, 25, 'facil', '/assets/images/recetas/papa_a_la_huancaina.jpg', 'Chicha morada', 'Huevo duro y aceituna', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (29, 2, 'Escabeche', 'Pescado frito bañado en un guiso agridulce de cebolla y ají panca.', '["4 filetes de pescado (800 g)","2 cebollas grandes, en pluma","3 cucharadas de ají panca, licuado","1/2 taza de vinagre","2 camotes"]'::jsonb, '["Sazonar los filetes de pescado con sal y pimienta, y pasarlos ligeramente por harina","Freír el pescado en aceite caliente hasta dorar por ambos lados, y reservar sobre papel absorbente","Cortar la cebolla en pluma gruesa y sofreírla en un poco de aceite hasta que empiece a transparentar sin perder su textura crocante","Añadir el ají panca licuado y cocinar 3 minutos a fuego medio","Incorporar el vinagre, un poco de agua o caldo, sal, pimienta y una pizca de azúcar, y hervir 5 minutos para que la cebolla se cocine a medias","Cocer el camote en agua con sal hasta que esté suave y cortarlo en rodajas","Colocar el pescado frito en una fuente y bañarlo con el escabeche caliente","Servir acompañado del camote y yuca sancochada, y decorar con huevo duro y aceitunas"]'::jsonb, 40, 'media', '/assets/images/recetas/escabeche.jpg', 'Chicha morada', 'Camote y yuca', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (30, 2, 'Pollo a la Brasa', 'Pollo marinado y asado a fuego lento hasta quedar dorado y jugoso.', '["1 pollo entero (2 kg aprox.)","4 cucharadas de ají panca","1 taza de cerveza negra","1 cucharadita de comino, orégano y pimienta","4 papas grandes, fritas"]'::jsonb, '["Limpiar bien el pollo entero, retirando exceso de grasa y secándolo con papel toalla","Licuar el ají panca junto con ajo, sal, comino, pimienta, orégano y un poco de cerveza negra hasta obtener una marinada espesa","Frotar el pollo con la marinada por dentro y por fuera, asegurándose de cubrir bien toda la superficie","Dejar reposar en refrigeración cubierto durante al menos 4 horas, idealmente toda la noche","Precalentar el horno o la parrilla a fuego medio-alto preparando una cocción indirecta","Colocar el pollo en una rejilla con una bandeja debajo para recoger los jugos, y asar volteando cada 20 minutos","Pincelar con más marinada o con los propios jugos durante la cocción para mantenerlo húmedo","Verificar el punto de cocción pinchando el muslo, hasta que los jugos salgan claros, aproximadamente 70 a 80 minutos en total","Dejar reposar 10 minutos antes de trozar y servir con papas fritas y ensalada"]'::jsonb, 100, 'dificil', '/assets/images/recetas/pollo_a_la_brasa.jpg', 'Gaseosa', 'Papas fritas y ensalada', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (31, 2, 'Arroz Chaufa', 'Arroz salteado al estilo chifa con huevo, cebolla china y sillao.', '["4 tazas de arroz cocido y frío","3 huevos","1 atado de cebolla china","4 cucharadas de sillao","300 g de pollo o carne, en cubos"]'::jsonb, '["Utilizar arroz cocido y frío, preferiblemente del día anterior, para que los granos queden sueltos","Batir los huevos con una pizca de sal, verterlos en un wok bien caliente con aceite y revolver rápido hasta cocinar en trozos pequeños; reservar","Cortar el pollo o la carne en cubos pequeños y saltearlos en el wok a fuego alto hasta dorar; reservar","Picar la cebolla china separando la parte blanca de la verde","En el mismo wok bien caliente, saltear la parte blanca de la cebolla china con un poco de aceite","Añadir el arroz frío y saltear a fuego alto, desmenuzando los grumos con la espátula para que se suelte","Incorporar el sillao poco a poco por los bordes del wok, mezclando rápido para que se distribuya de manera uniforme sin quedar aguado","Regresar el huevo y la carne al wok, añadir la parte verde de la cebolla china y saltear todo junto 2 minutos más","Servir bien caliente de inmediato"]'::jsonb, 20, 'facil', '/assets/images/recetas/arroz_chaufa.jpg', 'Chicha morada', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (32, 2, 'Tacu Tacu', 'Frejoles y arroz del día anterior dorados en sartén, servidos con bistec o mariscos.', '["2 tazas de frejoles cocidos","2 tazas de arroz cocido","1 ají amarillo, picado","1/2 cebolla, picada","4 bistecs"]'::jsonb, '["Sofreír cebolla picada y ají amarillo en un poco de aceite hasta que estén bien dorados","Aplastar los frejoles cocidos con un tenedor dejando algunos enteros para dar textura","Mezclar en un bowl los frejoles aplastados con el arroz cocido y el sofrito, sazonando con sal y comino","Calentar una sartén con aceite y verter la mezcla, extendiéndola y presionándola para formar una capa uniforme","Dorar a fuego medio sin mover durante unos 5 minutos hasta que se forme una costra dorada en la base","Doblar el tacu tacu sobre sí mismo como una tortilla y dorar el otro lado 3 minutos más","Sazonar y freír el bistec aparte con sal y pimienta hasta el punto deseado, o freír un huevo","Servir el tacu tacu caliente coronado con el bistec o el huevo frito"]'::jsonb, 30, 'media', '/assets/images/recetas/tacu_tacu.jpg', 'Chicha morada', 'Bistec o huevo frito', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (33, 2, 'Frejoles con seco', 'Frejoles canarios guisados servidos junto a un seco de carne.', '["2 tazas de frejoles canarios","600 g de carne de res, en trozos","1 atado de culantro, licuado","1 cebolla, picada","3 dientes de ajo"]'::jsonb, '["Remojar los frejoles canarios desde la noche anterior para acortar el tiempo de cocción","Cocer los frejoles en agua con un trozo de cebolla y ajo hasta que estén suaves, reservando el caldo de cocción","Sofreír cebolla y ajo picados en una olla aparte hasta que estén dorados","Incorporar los frejoles cocidos con un poco de su caldo y cocinar a fuego medio 15 minutos, sazonando con sal y comino","Sellar la carne de res en trozos en otra olla hasta dorar por todos lados","Licuar culantro con un poco de agua y añadirlo a la carne junto con cebolla y ajo sofritos","Cocinar la carne tapada a fuego lento durante 40 minutos, añadiendo caldo si se reduce demasiado, hasta que esté suave","Servir los frejoles guisados junto al seco de carne y una porción de arroz blanco"]'::jsonb, 60, 'media', '/assets/images/recetas/frejoles_con_seco.jpg', 'Chicha morada', 'Arroz blanco', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (34, 2, 'Estofado', 'Guiso de carne o pollo cocido lentamente en salsa de tomate.', '["800 g de carne o pollo, en trozos","3 tomates, picados","2 zanahorias, en trozos","3 papas, en trozos","1 taza de arvejas"]'::jsonb, '["Cortar la carne o el pollo en trozos medianos y sazonar con sal y pimienta","Sellar la carne en una olla con aceite caliente hasta dorar todos los lados, y reservar","Sofreír cebolla y ajo picados en la misma olla hasta que estén transparentes","Añadir el tomate picado o triturado y cocinar a fuego medio hasta que se deshaga formando una salsa","Regresar la carne a la olla, añadir un chorrito de vino o vinagre si se desea, y cubrir con caldo o agua","Cocinar tapado a fuego lento hasta que la carne esté tierna, entre 30 y 40 minutos según el corte","Incorporar la papa y la zanahoria en trozos, y cocinar 15 minutos más","Añadir las arvejas en los últimos 5 minutos de cocción","Rectificar la sazón y dejar que la salsa espese ligeramente antes de servir con arroz blanco"]'::jsonb, 60, 'media', '/assets/images/recetas/estofado.jpg', 'Chicha morada', 'Arroz blanco', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (35, 2, 'Pescado Frito', 'Filete de pescado frito y crocante, clásico de los almuerzos costeños.', '["4 filetes de pescado (800 g)","1 taza de harina","2 limones","Sal al gusto","2 tazas de aceite para freír"]'::jsonb, '["Secar bien los filetes de pescado con papel toalla para que la harina se adhiera mejor","Sazonar el pescado con sal, pimienta y jugo de limón, dejando reposar unos minutos","Pasar cada filete por harina, sacudiendo el exceso para lograr una capa fina y uniforme","Calentar abundante aceite en una sartén a fuego medio-alto hasta que esté bien caliente","Freír el pescado por tandas, sin sobrecargar la sartén, entre 3 y 4 minutos por lado hasta dorar","Retirar y colocar sobre papel absorbente para eliminar el exceso de aceite","Servir de inmediato con un toque extra de limón, arroz y ensalada fresca"]'::jsonb, 25, 'facil', '/assets/images/recetas/pescado_frito.jpg', 'Chicha morada', 'Arroz y ensalada', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (36, 2, 'Sudado', 'Pescado cocido a fuego lento en un guiso ligero de tomate y cebolla.', '["4 filetes o trozos de pescado (800 g)","2 tomates, en rodajas","1 cebolla grande, en pluma","1 ají amarillo, en tiras","1/2 atado de culantro, picado"]'::jsonb, '["Sazonar los trozos o filetes de pescado con sal, pimienta y un poco de limón","Cortar la cebolla en pluma gruesa y el tomate en rodajas","Sofreír la cebolla y el ají amarillo en tiras con un poco de aceite hasta que empiecen a ablandar","Añadir el tomate y cocinar 3 minutos, agregando un chorrito de agua o caldo de pescado","Colocar el pescado sazonado sobre el sofrito, cubriéndolo parcialmente con la cebolla y el tomate","Añadir culantro picado y tapar la olla, cocinando a fuego lento entre 12 y 15 minutos sin remover bruscamente para que el pescado no se rompa","Verificar que el pescado esté cocido y opaco por dentro antes de retirar","Servir caliente con el jugo del guiso, acompañado de arroz blanco"]'::jsonb, 35, 'media', '/assets/images/recetas/sudado.jpg', 'Chicha morada', 'Arroz blanco', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (37, 2, 'Ceviche', 'Pescado fresco marinado en limón con cebolla, ají y culantro.', '["600 g de pescado fresco, en cubos","10 limones (jugo)","1 cebolla roja grande, en pluma","2 ajíes limo, picados","1/2 atado de culantro, picado"]'::jsonb, '["Elegir pescado muy fresco y cortarlo en cubos parejos de aproximadamente 2 centímetros","Colocar el pescado en un bowl frío y sazonar con sal y un poco de ajo molido","Exprimir limones frescos hasta obtener suficiente jugo para cubrir el pescado por completo","Verter el jugo de limón sobre el pescado y mezclar suavemente, dejando marinar entre 5 y 10 minutos hasta que la carne cambie a un tono opaco","Cortar la cebolla roja en pluma fina y lavarla brevemente en agua fría para suavizar su sabor","Picar finamente el ají limo y el culantro","Incorporar la cebolla, el ají limo y el culantro al pescado marinado, mezclando con cuidado para no romper los trozos","Probar y ajustar la sal y el picante al gusto","Servir de inmediato bien frío, acompañado de camote sancochado y choclo"]'::jsonb, 20, 'media', '/assets/images/recetas/ceviche.jpg', 'Chicha morada', 'Camote y choclo', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO recetas (id, categoria_id, nombre, descripcion, ingredientes, preparacion, tiempo_minutos, dificultad, imagen_asset, bebida, acompanamiento, video_url) VALUES (38, 2, 'Arroz con Mariscos', 'Arroz meloso cocido con una mezcla generosa de mariscos.', '["3 tazas de arroz","800 g de mariscos mixtos","2 ajíes amarillos, licuados","1 pimiento, picado","1 atado de culantro, picado"]'::jsonb, '["Limpiar bien los mariscos mixtos, retirando conchas o impurezas según corresponda","Preparar un caldo rápido hirviendo las cáscaras o cabezas de los mariscos con un trozo de cebolla y apio, y colar","Sofreír cebolla, ajo, ají amarillo licuado y pimiento picado en una olla amplia con aceite hasta que estén bien cocidos","Añadir los mariscos más firmes primero (como calamar o pulpo) y saltear 2 minutos","Incorporar el resto de los mariscos y saltear brevemente hasta que tomen color, luego retirar la mitad para añadir al final y evitar que se pasen de cocción","Agregar el arroz lavado al sofrito y tostarlo un par de minutos para que absorba los sabores","Cubrir con el caldo caliente de mariscos y cocinar a fuego medio-bajo sin tapar del todo, removiendo ocasionalmente para lograr una textura melosa","Cuando el arroz esté casi en su punto, incorporar los mariscos reservados y el culantro picado","Cocinar unos minutos más hasta que el arroz esté cocido pero jugoso, y servir de inmediato"]'::jsonb, 45, 'dificil', '/assets/images/recetas/arroz_con_mariscos.jpg', 'Chicha morada', NULL, NULL) ON CONFLICT (id) DO NOTHING;
